#include <bits/stdc++.h>
using namespace std;using E=pair<int,int>;
int main(int argc,char**argv){int n=atoi(argv[1]),lim=atoi(argv[2]);vector<E> orig;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)orig.emplace_back(i,j);int m=orig.size(),all=(1<<n)-1;mt19937 rng(476734+n);int best=0,maximumMin=0;int bestCore=0;
 for(int z=0;z<lim;z++){auto a=orig;if(z%4==0)shuffle(a.begin(),a.end(),rng);else {if(z%4==3)reverse(a.begin(),a.end());int num=1+rng()%min(30,m);for(int i=0;i<num;i++)swap(a[rng()%m],a[rng()%m]);}int deg[16]={};int f=0;for(int sk=0;sk<m;sk++){int inf[16];for(int i=0;i<n;i++)inf[i]=1<<i;for(int i=0;i<m;i++)if(i!=sk){auto[u,v]=a[i];inf[u]|=inf[v];inf[v]=inf[u];}bool forced=0;for(int i=0;i<n;i++)if(inf[i]!=all){forced=1;break;}if(forced){f++;auto[u,v]=a[sk];deg[u]++;deg[v]++;}}
 int mn=99;for(auto [u,v]:{a.front(),a.back()}){mn=min(mn,deg[u]);mn=min(mn,deg[v]);}if(mn>maximumMin){maximumMin=mn;cerr<<"new max min degree on extremes "<<mn<<" at z="<<z<<" f="<<f<<"\n";}if(mn>=3){cout<<"WITNESS n="<<n<<" z="<<z<<" min_deg="<<mn<<" forced="<<f<<"\n";for(auto[u,v]:a)cout<<u<<","<<v<<" ";cout<<"\n";return 2;}best=max(best,f);}cout<<"PASS n="<<n<<" tested="<<lim<<" maxforced="<<best<<" extremal_min_degree="<<maximumMin<<"\n";}
